# Frozen default is 180 s of wall clock per decision attempt in the v187
# three-view tree.  The environment override exists only for explicitly
# authorized experimental lanes (slow agent-bridge models); queues that do not
# set it keep the frozen runtime behavior and recorded api_retry_policy
# byte-identical.
_DECISION_WALL_TIMEOUT_SECONDS: float | int = float(
    os.environ.get("BEHAVIOR_HL_ACTION20_DECISION_WALL_TIMEOUT_SECONDS", "180")
)
if not _DECISION_WALL_TIMEOUT_SECONDS > 0:
    raise ValueError(
        "BEHAVIOR_HL_ACTION20_DECISION_WALL_TIMEOUT_SECONDS must be positive"
    )
if float(_DECISION_WALL_TIMEOUT_SECONDS).is_integer():
    _DECISION_WALL_TIMEOUT_SECONDS = int(_DECISION_WALL_TIMEOUT_SECONDS)

