def _restricted_kinematic_turn_angle_deg(action_profile: str) -> float:
    """Resolve the explicit public turn bound for each action profile."""

    return (
        ACTION20_RESTRICTED_KINEMATIC_PUBLIC_TURN_DEG
        if action_profile == "marker_symbolic_action20"
        else RESTRICTED_KINEMATIC_PUBLIC_TURN_DEG
    )


_MINIMAL_ORACLE_BASE_POSITION_REFERENCE_M = 0.001
_MINIMAL_ORACLE_BASE_TILT_REFERENCE_DEG = 1.0
_MINIMAL_ORACLE_CAMERA_TRANSLATION_REFERENCE_M = 0.03
_MINIMAL_ORACLE_CAMERA_ROTATION_REFERENCE_DEG = 2.0
_MINIMAL_ORACLE_CAMERA_HEIGHT_REFERENCE_M = 0.25
_MINIMAL_ORACLE_VELOCITY_REFERENCE = 1.0e-3
